/*
 * keccak_rv32.c - Keccak-f[1600] permutation for RV32 (generated by
 * scripts/gen_keccak.py, do not edit).
 *
 * Replaces wolfCrypt's BlockSha3() (sha3.c is compiled with
 * -DWOLFSSL_RISCV_ASM, which only removes its own permutation). SHA-3 /
 * SHAKE is the core of ML-KEM and ML-DSA; wolfCrypt's generic version works
 * on 64-bit words, which this 32-bit core emulates. Here every lane is an
 * explicit (lo, hi) pair of 32-bit words, theta/rho/pi/chi/iota are fused
 * into one round that reads the state twice and writes it once, and only
 * one round is unrolled so the loop fits VexRiscv's 4 KB I-cache.
 */
#include <stdint.h>

#include <wolfssl/wolfcrypt/settings.h>
#include <wolfssl/wolfcrypt/types.h>

void BlockSha3(word64 *state);

static const uint32_t rc_lo[24] = { 0x00000001u, 0x00008082u, 0x0000808au, 0x80008000u, 0x0000808bu, 0x80000001u, 0x80008081u, 0x00008009u, 0x0000008au, 0x00000088u, 0x80008009u, 0x8000000au, 0x8000808bu, 0x0000008bu, 0x00008089u, 0x00008003u, 0x00008002u, 0x00000080u, 0x0000800au, 0x8000000au, 0x80008081u, 0x00008080u, 0x80000001u, 0x80008008u };
static const uint32_t rc_hi[24] = { 0x00000000u, 0x00000000u, 0x80000000u, 0x80000000u, 0x00000000u, 0x00000000u, 0x80000000u, 0x80000000u, 0x00000000u, 0x00000000u, 0x00000000u, 0x00000000u, 0x00000000u, 0x80000000u, 0x80000000u, 0x80000000u, 0x80000000u, 0x80000000u, 0x00000000u, 0x80000000u, 0x80000000u, 0x80000000u, 0x00000000u, 0x80000000u };

void BlockSha3(word64 *state)
{
    uint32_t tmp[50];
    uint32_t *s = (uint32_t *)state, *d = tmp;
    uint32_t c0l, c0h, c1l, c1h, c2l, c2h, c3l, c3h, c4l, c4h;
    uint32_t d0l, d0h, d1l, d1h, d2l, d2h, d3l, d3h, d4l, d4h;
    uint32_t b0l, b0h, b1l, b1h, b2l, b2h, b3l, b3h, b4l, b4h;
    uint32_t tl, th;
    

    
    for (int r = 0; r < 24; r++) {
        c0l = s[0] ^ s[10] ^ s[20] ^ s[30] ^ s[40];
        c0h = s[1] ^ s[11] ^ s[21] ^ s[31] ^ s[41];
        c1l = s[2] ^ s[12] ^ s[22] ^ s[32] ^ s[42];
        c1h = s[3] ^ s[13] ^ s[23] ^ s[33] ^ s[43];
        c2l = s[4] ^ s[14] ^ s[24] ^ s[34] ^ s[44];
        c2h = s[5] ^ s[15] ^ s[25] ^ s[35] ^ s[45];
        c3l = s[6] ^ s[16] ^ s[26] ^ s[36] ^ s[46];
        c3h = s[7] ^ s[17] ^ s[27] ^ s[37] ^ s[47];
        c4l = s[8] ^ s[18] ^ s[28] ^ s[38] ^ s[48];
        c4h = s[9] ^ s[19] ^ s[29] ^ s[39] ^ s[49];
        d0l = c4l ^ ((c1l << 1) | (c1h >> 31));
        d0h = c4h ^ ((c1h << 1) | (c1l >> 31));
        d1l = c0l ^ ((c2l << 1) | (c2h >> 31));
        d1h = c0h ^ ((c2h << 1) | (c2l >> 31));
        d2l = c1l ^ ((c3l << 1) | (c3h >> 31));
        d2h = c1h ^ ((c3h << 1) | (c3l >> 31));
        d3l = c2l ^ ((c4l << 1) | (c4h >> 31));
        d3h = c2h ^ ((c4h << 1) | (c4l >> 31));
        d4l = c3l ^ ((c0l << 1) | (c0h >> 31));
        d4h = c3h ^ ((c0h << 1) | (c0l >> 31));
        tl = s[0] ^ d0l; th = s[1] ^ d0h;
        b0l = tl; b0h = th;
        tl = s[12] ^ d1l; th = s[13] ^ d1h;
        b1l = (th << 12) | (tl >> 20);
        b1h = (tl << 12) | (th >> 20);
        tl = s[24] ^ d2l; th = s[25] ^ d2h;
        b2l = (th << 11) | (tl >> 21);
        b2h = (tl << 11) | (th >> 21);
        tl = s[36] ^ d3l; th = s[37] ^ d3h;
        b3l = (tl << 21) | (th >> 11);
        b3h = (th << 21) | (tl >> 11);
        tl = s[48] ^ d4l; th = s[49] ^ d4h;
        b4l = (tl << 14) | (th >> 18);
        b4h = (th << 14) | (tl >> 18);
        d[0] = (b0l ^ (~b1l & b2l)) ^ rc_lo[r];
        d[1] = (b0h ^ (~b1h & b2h)) ^ rc_hi[r];
        d[2] = b1l ^ (~b2l & b3l);
        d[3] = b1h ^ (~b2h & b3h);
        d[4] = b2l ^ (~b3l & b4l);
        d[5] = b2h ^ (~b3h & b4h);
        d[6] = b3l ^ (~b4l & b0l);
        d[7] = b3h ^ (~b4h & b0h);
        d[8] = b4l ^ (~b0l & b1l);
        d[9] = b4h ^ (~b0h & b1h);
        tl = s[6] ^ d3l; th = s[7] ^ d3h;
        b0l = (tl << 28) | (th >> 4);
        b0h = (th << 28) | (tl >> 4);
        tl = s[18] ^ d4l; th = s[19] ^ d4h;
        b1l = (tl << 20) | (th >> 12);
        b1h = (th << 20) | (tl >> 12);
        tl = s[20] ^ d0l; th = s[21] ^ d0h;
        b2l = (tl << 3) | (th >> 29);
        b2h = (th << 3) | (tl >> 29);
        tl = s[32] ^ d1l; th = s[33] ^ d1h;
        b3l = (th << 13) | (tl >> 19);
        b3h = (tl << 13) | (th >> 19);
        tl = s[44] ^ d2l; th = s[45] ^ d2h;
        b4l = (th << 29) | (tl >> 3);
        b4h = (tl << 29) | (th >> 3);
        d[10] = b0l ^ (~b1l & b2l);
        d[11] = b0h ^ (~b1h & b2h);
        d[12] = b1l ^ (~b2l & b3l);
        d[13] = b1h ^ (~b2h & b3h);
        d[14] = b2l ^ (~b3l & b4l);
        d[15] = b2h ^ (~b3h & b4h);
        d[16] = b3l ^ (~b4l & b0l);
        d[17] = b3h ^ (~b4h & b0h);
        d[18] = b4l ^ (~b0l & b1l);
        d[19] = b4h ^ (~b0h & b1h);
        tl = s[2] ^ d1l; th = s[3] ^ d1h;
        b0l = (tl << 1) | (th >> 31);
        b0h = (th << 1) | (tl >> 31);
        tl = s[14] ^ d2l; th = s[15] ^ d2h;
        b1l = (tl << 6) | (th >> 26);
        b1h = (th << 6) | (tl >> 26);
        tl = s[26] ^ d3l; th = s[27] ^ d3h;
        b2l = (tl << 25) | (th >> 7);
        b2h = (th << 25) | (tl >> 7);
        tl = s[38] ^ d4l; th = s[39] ^ d4h;
        b3l = (tl << 8) | (th >> 24);
        b3h = (th << 8) | (tl >> 24);
        tl = s[40] ^ d0l; th = s[41] ^ d0h;
        b4l = (tl << 18) | (th >> 14);
        b4h = (th << 18) | (tl >> 14);
        d[20] = b0l ^ (~b1l & b2l);
        d[21] = b0h ^ (~b1h & b2h);
        d[22] = b1l ^ (~b2l & b3l);
        d[23] = b1h ^ (~b2h & b3h);
        d[24] = b2l ^ (~b3l & b4l);
        d[25] = b2h ^ (~b3h & b4h);
        d[26] = b3l ^ (~b4l & b0l);
        d[27] = b3h ^ (~b4h & b0h);
        d[28] = b4l ^ (~b0l & b1l);
        d[29] = b4h ^ (~b0h & b1h);
        tl = s[8] ^ d4l; th = s[9] ^ d4h;
        b0l = (tl << 27) | (th >> 5);
        b0h = (th << 27) | (tl >> 5);
        tl = s[10] ^ d0l; th = s[11] ^ d0h;
        b1l = (th << 4) | (tl >> 28);
        b1h = (tl << 4) | (th >> 28);
        tl = s[22] ^ d1l; th = s[23] ^ d1h;
        b2l = (tl << 10) | (th >> 22);
        b2h = (th << 10) | (tl >> 22);
        tl = s[34] ^ d2l; th = s[35] ^ d2h;
        b3l = (tl << 15) | (th >> 17);
        b3h = (th << 15) | (tl >> 17);
        tl = s[46] ^ d3l; th = s[47] ^ d3h;
        b4l = (th << 24) | (tl >> 8);
        b4h = (tl << 24) | (th >> 8);
        d[30] = b0l ^ (~b1l & b2l);
        d[31] = b0h ^ (~b1h & b2h);
        d[32] = b1l ^ (~b2l & b3l);
        d[33] = b1h ^ (~b2h & b3h);
        d[34] = b2l ^ (~b3l & b4l);
        d[35] = b2h ^ (~b3h & b4h);
        d[36] = b3l ^ (~b4l & b0l);
        d[37] = b3h ^ (~b4h & b0h);
        d[38] = b4l ^ (~b0l & b1l);
        d[39] = b4h ^ (~b0h & b1h);
        tl = s[4] ^ d2l; th = s[5] ^ d2h;
        b0l = (th << 30) | (tl >> 2);
        b0h = (tl << 30) | (th >> 2);
        tl = s[16] ^ d3l; th = s[17] ^ d3h;
        b1l = (th << 23) | (tl >> 9);
        b1h = (tl << 23) | (th >> 9);
        tl = s[28] ^ d4l; th = s[29] ^ d4h;
        b2l = (th << 7) | (tl >> 25);
        b2h = (tl << 7) | (th >> 25);
        tl = s[30] ^ d0l; th = s[31] ^ d0h;
        b3l = (th << 9) | (tl >> 23);
        b3h = (tl << 9) | (th >> 23);
        tl = s[42] ^ d1l; th = s[43] ^ d1h;
        b4l = (tl << 2) | (th >> 30);
        b4h = (th << 2) | (tl >> 30);
        d[40] = b0l ^ (~b1l & b2l);
        d[41] = b0h ^ (~b1h & b2h);
        d[42] = b1l ^ (~b2l & b3l);
        d[43] = b1h ^ (~b2h & b3h);
        d[44] = b2l ^ (~b3l & b4l);
        d[45] = b2h ^ (~b3h & b4h);
        d[46] = b3l ^ (~b4l & b0l);
        d[47] = b3h ^ (~b4h & b0h);
        d[48] = b4l ^ (~b0l & b1l);
        d[49] = b4h ^ (~b0h & b1h);
        uint32_t *t = s; s = d; d = t;   /* 24 rounds: ends back in state */
    }
}
